      <button
        hlmBtn
        variant="ghost"
        size="icon-sm"
        type="button"
        aria-label="Notifications"
        hlmTooltip="Notifications"
      >
        <ng-icon name="lucideBell" />
      </button>

      <button
        hlmBtn
        variant="ghost"
        size="icon-sm"
        type="button"
        [attr.aria-label]="vm.isDark() ? 'Switch to light theme' : 'Switch to dark theme'"
        [hlmTooltip]="vm.isDark() ? 'Switch to light theme' : 'Switch to dark theme'"
        (click)="vm.toggleTheme()"
