        <ng-icon [name]="vm.isDark() ? 'lucideSun' : 'lucideMoon'" />
      </button>

      <hlm-avatar class="app__avatar">
        <span hlmAvatarFallback>CO</span>
      </hlm-avatar>
    </header>

    <div class="app__content">
      <router-outlet />
    </div>
  </main>
</div>
